--
-- Table structure for table `jam_belajar`
--

DROP TABLE IF EXISTS `jam_belajar`;
CREATE TABLE IF NOT EXISTS `jam_belajar` (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `hari` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `urutan` int NOT NULL DEFAULT '1' COMMENT 'Nomor urut jam (jam ke-1, jam ke-2, dst)',
  `jam_mulai` time DEFAULT NULL,
  `jam_selesai` time DEFAULT NULL,
  `jenis` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=53 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

